class Solution {
    fun maxSideLength(mat:Array<IntArray>,threshold:Int):Int{
        val rows=mat.size;
        val columns=mat[0].size;
        val prefix=Array(rows+1){
            IntArray(columns+1)
        };
        for(r in 0 until rows)for(c in 0 until columns)prefix[r+1][c+1]=mat[r][c]+prefix[r][c+1]+prefix[r+1][c]-prefix[r][c];
        fun feasible(side:Int):Boolean{
            for(r in side..rows)for(c in side..columns)if(prefix[r][c]-prefix[r-side][c]-prefix[r][c-side]+prefix[r-side][c-side]<=threshold)return true;
            return false
        };
        var left=0;
        var right=minOf(rows,columns);
        while(left<right){
            val middle=(left+right+1)/2;
            if(feasible(middle))left=middle else right=middle-1
        };
        return left
    }
}

